#include <stdio.h>

int main(void) {
    int values[] = {8, 3, 5, 1};
    size_t count = sizeof values / sizeof values[0];
    int total = 0;
    int largest = values[0];
    for (size_t i = 0; i < count; ++i) {
        total += values[i];
        if (values[i] > largest) largest = values[i];
    }
    printf("count=%zu total=%d largest=%d\n", count, total, largest);
    return 0;
}
